assert Path.cwd()==r
assert os.environ.get('GIT_OPTIONAL_LOCKS')=='0'
p=r/'.ci/native-preservation.json'
assert p.is_file() and not p.is_symlink()
record=json.loads(p.read_text())
sha=lambda b:hashlib.sha256(b).hexdigest()
assert subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip()==record['head']=='03a8274a51d8ede7873d92f745479736e13d8d33'
