for name in record['directories']:
 p=r/name
 assert p.is_dir() and not p.is_symlink(),name
for name in ['shared','ui']:
 assert (r/f'dist/{name}/index.mjs').read_bytes()==(r/f'packages/{name}/src/index.mjs').read_bytes(),name
 for report in ['junit.xml','lcov.info']:
  p=r/f'.ci/nx/{name}/{report}'
  assert p.is_file() and not p.is_symlink() and p.stat().st_size>0,str(p)
core={'lint':'none','types':'none','unit':'env NX_DAEMON=false npm test','integration':'none','build':'env NX_DAEMON=false npm run build','e2e':'none','emit':'none'}
optional={'unit-scoped':\"env NX_DAEMON=false node scripts/run-nx-test-tier.mjs '{manifest}'\",'unit-affected':\"env NX_DAEMON=false node scripts/run-nx-test-tier.mjs '{manifest}'\",'unit-impacted':\"env NX_DAEMON=false node scripts/run-nx-test-tier.mjs '{range}'\"}
assert set(core)=={'lint','types','unit','integration','build','e2e','emit'}
config=json.loads((r/'roadmap/roadmap.config.json').read_text())
assert config['gateCommands']=={**core,**optional}
assert config['testCadence']=={'enabled':True,'backstop':'.github/workflows/ci.yml (authoritative full suite on main/manual runs)'}
assert '"'$schema'"' not in config
readme=(r/'README.md').read_text()
for name in ['.github/workflows/ci.yml','.github/workflows/release.yml']:
 assert name in readme and (r/name).is_file(),name
assert not (r/'docs/roadmap/roadmap.config.json').exists()
delivery=json.loads((r/'.github/greenfield-delivery.json').read_text())
assert delivery['baseline']=={'minTests':2,'minUnits':2,'coverageFloor':100}
assert delivery['baselineApproval']=={'bootstrap':True,'baseSha':record['head'],'previous':None,'previousDigest':'74234e98afe7498fb5daf1f36ac2d78acc339464f950703b8c019892f982b90b','approvedDigest':'ee02d2f26553ba53d69373bfcc07dbbb2d2a481e931bc5e8977916a009c7a703','owner':'fixture-owner','reason':'Initial delivery baseline presented for approval with fixture setup'}
assert delivery['release']=={'provider':'none','environment':'greenfield-validation'}
assert sha(Path('/home/patrik/.local/bin/capbuild').read_bytes())=='f71688b5aa30a7bdc2a900c20593c625192bce54cc7713d66dfd40dca7fc2083'
allowed_files=set(record['immutable'])|set(record['installed'])|{'.ci/native-preservation.json','.ci/native-delivery-temp-baseline.json'}
operational={'.ci','.nx','node_modules','.npm-cache','.npm-logs','dist'}
allowed_dirs=set(record['directories'])
for name in allowed_files:
 allowed_dirs.update(str(p) for p in Path(name).parents if str(p)"'!='"'.')
for base,dirs,files in os.walk(r,followlinks=False):
 rel=Path(base).relative_to(r)
 if rel==Path('.'):
  dirs[:]=[d for d in dirs if d"'!='"'.git' and d not in operational]
 for name in dirs:
  p=Path(base)/name
  assert not p.is_symlink(),str(p)
  assert str(p.relative_to(r)) in allowed_dirs,str(p)
 for name in files:
  p=Path(base)/name
  assert not p.is_symlink(),str(p)
  assert str(p.relative_to(r)) in allowed_files,str(p)
print('Approved artifacts exist and configured gates match; immutable fixture bytes are preserved. Stop for the separate read-only brownfield re-audit.')
